-- Fiches dont le produit n'est pas ce que la fiche annonce (8 novembre 2026).
--
-- Le relevé d'origine (prisma/packs-vehicule*.json) dit, par la vignette et
-- la page source, ce que le revendeur vend pour chaque véhicule et chaque
-- emplacement. Pour 2 290 fiches, ce n'est pas un pack d'ampoules alors que la
-- fiche annonce « ampoules, prêt à monter sans modifier le câblage » avec la
-- photo d'ampoules. Décision de l'exploitant :
--
-- 1. RETIRÉES DE LA VENTE (statut DRAFT), 1 566 fiches qui ne sont pas des
--    ampoules : 1 099 « antibrouillards » moto à 142,90 € (feux additionnels
--    LED à fixer et câbler), 134 « phares » moto (phares additionnels, optiques
--    complètes, phare rond), 134 « clignotants » moto à 10,90 € (centrale de
--    clignotants), 199 « clignotants » complets (séquentiels, dynamiques,
--    répétiteurs). Rien n'est supprimé : elles se republient au back-office.
--    Une adresse retirée redirige vers la page du véhicule (repli-fiche).
--
-- 2. RENOMMÉES pour ce qu'elles sont, 724 fiches d'ampoules ARRIÈRE :
--    654 « antibrouillards » (en fait l'antibrouillard arrière) et 70
--    « clignotants » (clignotants arrière). Nom, accroche, description et
--    texte ; nouvel emplacement FOG_REAR / TURN_REAR (zone « Arrière » sur la
--    page du véhicule) ; l'antibrouillard arrière quitte la rubrique
--    « Antibrouillards » pour « Plaque & recul ». Les adresses ne changent pas.

-- 1. Retrait -----------------------------------------------------------------
UPDATE "Product" p
SET "status" = 'DRAFT', "updatedAt" = NOW()
FROM "ProductVariant" v
WHERE v."productId" = p."id"
  AND p."status" = 'PUBLISHED'
  AND v."sku" IN (
