UPDATE "Product" p
SET
  "name" = replace(p."name", 'antibrouillards pour', 'antibrouillard arrière pour'),
  "tagline" = replace(p."tagline", 'Pour les antibrouillards de', 'Pour l’antibrouillard arrière de'),
  "description" = replace(p."description", 'pour les antibrouillards de', 'pour l’antibrouillard arrière de'),
  "body" = replace(replace(replace(p."body",
    'Les ampoules d''antibrouillards avant.',
    'L’éclairage de l’antibrouillard arrière : le feu rouge qui s’allume à l’arrière par brouillard épais.'),
    'Un antibrouillard se loge dans le pare-chocs, un emplacement confiné et exposé aux projections. **Contrôlez l''étanchéité du cache arrière** avant de refermer : c''est par là que l''eau entre.',
    'L’antibrouillard arrière ne sert que par brouillard épais ou forte pluie, et on oublie souvent de le vérifier. **Testez-le après le montage** : il doit s’allumer avec la commande d’antibrouillard, et rester bien visible derrière vous.'),
    'Les antibrouillards, et rien d''autre.',
    'L’antibrouillard arrière, et rien d''autre.'),
  "updatedAt" = NOW()
FROM "ProductVariant" v
