UPDATE "Product" p
SET
  "name" = replace(p."name", 'clignotants pour', 'clignotants arrière pour'),
  "tagline" = replace(p."tagline", 'Pour les clignotants de', 'Pour les clignotants arrière de'),
  "description" = replace(p."description", 'pour les clignotants de', 'pour les clignotants arrière de'),
  "body" = replace(replace(p."body",
    'Les clignotants.',
    'Les clignotants arrière.'),
    'Les clignotants, et rien d''autre.',
    'Les clignotants arrière, et rien d''autre.'),
